mkdir -p /app/output/assets && cat > /app/output/assets/styles.css <<'CSS'
:root{
  /* Brand (OKLCH) */
  --dc-bg: oklch(98.5% 0.004 260);
  --dc-surface: oklch(99.4% 0.002 260);
  --dc-surface-2: oklch(97.2% 0.006 260);
  --dc-text: oklch(18% 0.02 260);
  --dc-text-2: oklch(42% 0.02 260);
  --dc-text-3: oklch(58% 0.015 260);
  --dc-border: oklch(90% 0.01 260);
  --dc-border-2: oklch(86% 0.012 260);

  --dc-blue: oklch(56% 0.23 265);
  --dc-blue-2: oklch(62% 0.18 265);
  --dc-blue-soft: oklch(93% 0.04 265);
  --dc-orange: oklch(72% 0.18 52);

  --shadow-sm: 0 1px 2px rgba(17,17,17,0.06);
  --shadow-md: 0 10px 30px rgba(17,17,17,0.10);

  --radius-sm: 10px;
  --radius-md: 14px;
  --radius-lg: 18px;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;

  --container: 1200px;
}

*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Inter, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
  color: var(--dc-text);
  background: radial-gradient(1200px 600px at 10% -20%, var(--dc-blue-soft), transparent 60%),
              radial-gradient(800px 500px at 95% 0%, oklch(96% 0.02 52), transparent 55%),
              var(--dc-bg);
  line-height: 1.55;
}

a{color:inherit; text-decoration:none}
a:hover{text-decoration:none}

.container{
  width:100%;
  max-width: var(--container);
  margin:0 auto;
  padding: 0 var(--space-3);
}

.skip-link{
  position:absolute; left:-999px; top:0;
  background: var(--dc-surface);
  border:1px solid var(--dc-border);
  padding: 10px 12px;
  border-radius: 10px;
  z-index: 9999;
}
.skip-link:focus{left:12px; top:12px}

.topbar{
  position: sticky;
  top: 0;
  z-index: 80;
  border-bottom: 1px solid color-mix(in oklch, var(--dc-border), transparent 35%);
  background: color-mix(in oklch, var(--dc-surface), transparent 10%);
  backdrop-filter: blur(10px);
}

.nav{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: var(--space-3);
  padding: 14px 0;
}

.brand{
  display:flex;
  align-items:center;
  gap: 10px;
  min-width: 180px;
}

.logo{
  width: 32px;
  height: 32px;
  border-radius: 10px;
  background: radial-gradient(120% 120% at 10% 0%, color-mix(in oklch, var(--dc-blue), white 15%), var(--dc-blue));
  box-shadow: var(--shadow-sm);
  display:grid;
  place-items:center;
  color: white;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.brand-title{
  display:flex;
  flex-direction:column;
  line-height:1.1;
}

.brand-title strong{font-size: 14px; letter-spacing:-0.01em}
.brand-title span{font-size: 12px; color: var(--dc-text-2)}

.nav-links{display:flex; align-items:center; gap: 6px; flex-wrap:wrap}

.nav-link, .nav-trigger{
  border: 1px solid transparent;
  padding: 10px 12px;
  border-radius: 12px;
  color: var(--dc-text);
  font-weight: 560;
  font-size: 14px;
  background: transparent;
  cursor:pointer;
}

.nav-link:hover, .nav-trigger:hover{
  background: color-mix(in oklch, var(--dc-surface-2), transparent 0%);
  border-color: color-mix(in oklch, var(--dc-border), transparent 20%);
}

.nav-actions{display:flex; align-items:center; gap: 10px}

.btn{
  border: 1px solid var(--dc-border);
  background: var(--dc-surface);
  padding: 10px 12px;
  border-radius: 12px;
  font-weight: 600;
  font-size: 14px;
  cursor:pointer;
  box-shadow: 0 0 0 rgba(0,0,0,0);
  transition: transform .14s ease, box-shadow .14s ease, border-color .14s ease;
}

.btn:hover{transform: translateY(-1px); box-shadow: var(--shadow-sm); border-color: var(--dc-border-2)}

.btn-primary{
  border-color: color-mix(in oklch, var(--dc-blue), black 10%);
  background: linear-gradient(180deg, color-mix(in oklch, var(--dc-blue), white 10%), var(--dc-blue));
  color: white;
}

.btn-primary:hover{box-shadow: 0 12px 30px rgba(0,114,245,0.22)}

.btn-ghost{
  background: transparent;
}

.btn-ai{
  border-color: color-mix(in oklch, var(--dc-blue), transparent 55%);
  background: color-mix(in oklch, var(--dc-blue-soft), transparent 10%);
}

.btn-small{padding: 9px 11px; border-radius: 999px}

.hamburger{display:none}

/* Mega menu */
.mega-wrap{position:relative}
.mega{
  position:absolute;
  left: 0;
  top: calc(100% + 10px);
  width: min(860px, calc(100vw - 32px));
  border: 1px solid var(--dc-border);
  background: color-mix(in oklch, var(--dc-surface), transparent 0%);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  padding: 16px;
  display:none;
}

.mega[data-open="true"]{display:block}

.mega-grid{
  display:grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 14px;
}

.mega-col{
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 35%);
  border-radius: var(--radius-md);
  padding: 14px;
  background: linear-gradient(180deg, color-mix(in oklch, var(--dc-surface), white 0%), color-mix(in oklch, var(--dc-surface-2), transparent 0%));
}

.mega-col h4{margin:0 0 10px 0; font-size: 13px; letter-spacing: 0.02em; text-transform: uppercase; color: var(--dc-text-2)}

.mega-list{display:grid; gap: 6px}

.mega-item{
  display:flex;
  align-items:flex-start;
  gap: 10px;
  padding: 10px;
  border-radius: 12px;
  border: 1px solid transparent;
}

.mega-item:hover{
  background: color-mix(in oklch, var(--dc-blue-soft), transparent 35%);
  border-color: color-mix(in oklch, var(--dc-border), transparent 25%);
}

.mega-badge{
  width: 28px;
  height: 28px;
  border-radius: 10px;
  background: color-mix(in oklch, var(--dc-blue-soft), transparent 0%);
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 35%);
  display:grid;
  place-items:center;
  color: var(--dc-blue);
  font-weight: 750;
  font-size: 12px;
  flex: 0 0 auto;
}

.mega-item strong{display:block; font-size: 14px; letter-spacing: -0.01em}
.mega-item span{display:block; font-size: 12px; color: var(--dc-text-2)}

/* Hero / header intro */
.hero{
  padding: 36px 0 20px;
}

.hero-head{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap: 18px;
  padding: 26px 0 10px;
}

.kicker{
  display:inline-flex;
  align-items:center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 999px;
  background: color-mix(in oklch, var(--dc-blue-soft), transparent 10%);
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 25%);
  color: var(--dc-text);
  font-size: 13px;
  font-weight: 600;
}

.kicker .dot{
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--dc-blue);
  box-shadow: 0 0 0 4px color-mix(in oklch, var(--dc-blue), transparent 75%);
}

h1{
  margin: 10px 0 0;
  font-size: clamp(28px, 3.2vw, 44px);
  letter-spacing: -0.03em;
  line-height: 1.05;
}

.subhead{
  margin: 10px 0 0;
  color: var(--dc-text-2);
  font-size: 16px;
  max-width: 64ch;
}

.hero-right{
  display:flex;
  align-items:center;
  gap: 10px;
}

/* Filters */
.filters{
  display:flex;
  align-items:center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0 18px;
  border-bottom: 1px solid color-mix(in oklch, var(--dc-border), transparent 20%);
}

.pills{display:flex; flex-wrap:wrap; gap: 8px}

.pill{
  border: 1px solid var(--dc-border);
  background: color-mix(in oklch, var(--dc-surface), transparent 0%);
  color: var(--dc-text);
  padding: 9px 12px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 650;
  cursor:pointer;
  transition: background .14s ease, border-color .14s ease, transform .14s ease;
}

.pill:hover{transform: translateY(-1px); border-color: var(--dc-border-2)}

.pill[aria-pressed="true"]{
  background: color-mix(in oklch, var(--dc-blue), white 88%);
  border-color: color-mix(in oklch, var(--dc-blue), transparent 45%);
  color: color-mix(in oklch, var(--dc-blue), black 18%);
}

.search{
  flex: 0 0 min(360px, 100%);
  display:flex;
  gap: 8px;
  align-items:center;
}

.search input{
  width:100%;
  padding: 11px 12px;
  border-radius: 12px;
  border: 1px solid var(--dc-border);
  background: color-mix(in oklch, var(--dc-surface), transparent 0%);
  font-size: 14px;
  outline: none;
}

.search input:focus-visible{
  border-color: color-mix(in oklch, var(--dc-blue), transparent 20%);
  box-shadow: 0 0 0 4px color-mix(in oklch, var(--dc-blue), transparent 80%);
}

/* Featured */
.section{padding: 26px 0}
.section-title{
  display:flex;
  align-items:baseline;
  justify-content:space-between;
  gap: 16px;
  margin: 0 0 14px;
}
.section-title h2{margin:0; font-size: 18px; letter-spacing:-0.01em}
.section-title p{margin:0; color: var(--dc-text-2); font-size: 14px}

.featured-grid{
  display:grid;
  grid-template-columns: 1.35fr 0.65fr;
  gap: 14px;
}

.featured-main{
  display:grid;
  grid-template-columns: 1fr;
}

.featured-side{display:grid; gap: 14px}

.card{
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 0%);
  background: color-mix(in oklch, var(--dc-surface), transparent 0%);
  border-radius: var(--radius-lg);
  overflow:hidden;
  box-shadow: 0 0 0 rgba(0,0,0,0);
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease;
}

.card:hover{transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: color-mix(in oklch, var(--dc-border-2), transparent 0%)}

.card a{display:block; height:100%}

.card-inner{padding: 16px}

.card-top{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.tag{
  display:inline-flex;
  align-items:center;
  gap: 6px;
  padding: 7px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 15%);
  background: color-mix(in oklch, var(--dc-surface-2), transparent 0%);
  font-size: 12px;
  font-weight: 650;
  color: var(--dc-text);
}

.tag .swatch{width: 8px; height: 8px; border-radius: 99px; background: var(--dc-blue)}

.meta{font-size: 12px; color: var(--dc-text-2)}

.card h3{margin: 6px 0 8px; font-size: 18px; letter-spacing: -0.02em; line-height: 1.18}

.card p{margin: 0; color: var(--dc-text-2); font-size: 14px}

.card-footer{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: 10px;
  margin-top: 14px;
}

.author{
  display:flex;
  align-items:center;
  gap: 10px;
  min-width: 0;
}

.avatar{
  width: 28px;
  height: 28px;
  border-radius: 999px;
  display:grid;
  place-items:center;
  color: white;
  font-weight: 750;
  font-size: 12px;
  background: linear-gradient(180deg, color-mix(in oklch, var(--dc-blue), white 18%), var(--dc-blue));
  border: 1px solid color-mix(in oklch, var(--dc-blue), transparent 50%);
}

.author span{font-size: 13px; color: var(--dc-text); font-weight: 600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}

.readtime{font-size: 12px; color: var(--dc-text-2)}

/* Featured styling */
.featured-hero{
  position:relative;
  background:
    radial-gradient(900px 520px at 10% 0%, color-mix(in oklch, var(--dc-blue-soft), transparent 0%), transparent 60%),
    linear-gradient(180deg, color-mix(in oklch, var(--dc-surface), transparent 0%), color-mix(in oklch, var(--dc-surface-2), transparent 0%));
}

.featured-hero .card-inner{padding: 22px}

.featured-hero h3{font-size: clamp(20px, 2vw, 28px)}

.stats{
  display:grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 10px;
  margin-top: 16px;
}

.stat{
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 10%);
  background: color-mix(in oklch, var(--dc-surface), transparent 0%);
  border-radius: 14px;
  padding: 12px;
}

.stat strong{display:block; font-size: 16px; letter-spacing: -0.02em}
.stat span{display:block; font-size: 12px; color: var(--dc-text-2); margin-top: 4px}

/* Latest */
.grid{
  display:grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 14px;
}

.card.compact h3{font-size: 16px}

.card.compact .card-inner{padding: 14px}

.controls-row{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: 10px;
  margin: 14px 0 0;
}

.muted{color: var(--dc-text-2); font-size: 13px}

.no-results{
  border: 1px dashed color-mix(in oklch, var(--dc-border-2), transparent 0%);
  border-radius: var(--radius-lg);
  padding: 20px;
  background: color-mix(in oklch, var(--dc-surface), transparent 0%);
  display:none;
}

.no-results[data-show="true"]{display:block}

/* CTA */
.cta{
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 0%);
  border-radius: var(--radius-lg);
  background: linear-gradient(180deg, color-mix(in oklch, var(--dc-blue-soft), transparent 0%), color-mix(in oklch, var(--dc-surface), transparent 0%));
  padding: 22px;
  display:grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 14px;
  align-items:center;
}

.cta h3{margin:0 0 8px; font-size: 20px; letter-spacing: -0.02em}
.cta p{margin:0; color: var(--dc-text-2)}

.cta-actions{display:flex; gap: 10px; flex-wrap:wrap; justify-content:flex-end}

.enterprise{
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 10%);
  background: color-mix(in oklch, var(--dc-surface), transparent 0%);
  border-radius: 14px;
  padding: 14px;
}

.enterprise strong{display:block}
.enterprise span{display:block; color: var(--dc-text-2); font-size: 13px; margin-top: 6px}

/* Footer */
.footer{
  padding: 40px 0 60px;
  border-top: 1px solid color-mix(in oklch, var(--dc-border), transparent 20%);
  margin-top: 26px;
}

.footer-grid{
  display:grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 16px;
}

.footer h4{margin: 0 0 10px; font-size: 12px; letter-spacing: 0.03em; text-transform: uppercase; color: var(--dc-text-2)}

.footer a{
  display:block;
  padding: 6px 0;
  color: var(--dc-text);
  font-size: 13px;
}

.footer a:hover{color: color-mix(in oklch, var(--dc-blue), black 18%)}

.footer-bottom{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: 10px;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid color-mix(in oklch, var(--dc-border), transparent 25%);
  color: var(--dc-text-2);
  font-size: 13px;
}

.status{
  display:inline-flex;
  align-items:center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in oklch, var(--dc-border), transparent 30%);
  background: color-mix(in oklch, var(--dc-surface), transparent 0%);
}

.status .pulse{
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: oklch(68% 0.18 145);
  box-shadow: 0 0 0 4px color-mix(in oklch, oklch(68% 0.18 145), transparent 75%);
}

/* Accessibility / motion */
:focus-visible{outline: 2px solid var(--dc-blue); outline-offset: 2px}

@media (prefers-reduced-motion: reduce){
  *{scroll-behavior:auto !important}
  .card, .btn, .pill{transition:none !important}
}

/* Responsive */
@media (max-width: 980px){
  .featured-grid{grid-template-columns: 1fr}
  .stats{grid-template-columns: 1fr}
  .cta{grid-template-columns: 1fr}
  .cta-actions{justify-content:flex-start}
  .grid{grid-template-columns: repeat(2, minmax(0,1fr))}
  .footer-grid{grid-template-columns: repeat(2, minmax(0,1fr))}
}

@media (max-width: 740px){
  .nav-links{display:none}
  .hamburger{display:inline-flex}
  .hero-head{flex-direction:column; align-items:flex-start}
  .filters{flex-direction:column; align-items:stretch}
  .search{flex: 1 1 auto}
  .grid{grid-template-columns: 1fr}
  .footer-grid{grid-template-columns: 1fr}
  .brand{min-width:auto}
}

/* Mobile menu */
.mobile-menu{
  display:none;
  border-top: 1px solid color-mix(in oklch, var(--dc-border), transparent 20%);
  padding: 10px 0 14px;
}

.mobile-menu[data-open="true"]{display:block}

.mobile-menu .row{display:flex; flex-wrap:wrap; gap: 8px}

.sr-only{
  position:absolute;
  width:1px;height:1px;
  padding:0;margin:-1px;
  overflow:hidden;clip:rect(0,0,0,0);
  white-space:nowrap;border:0;
}
